import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor min_reduce_forward(torch::Tensor x, int64_t dim);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <vector>

using namespace cute;

__global__ void min_reduce_kernel(
    const float* __restrict__ X,
    float* __restrict__ Y,
    int outer, int R, int inner)
{
    int total = outer * inner;
    int stride = blockDim.x * gridDim.x;
    // Use direct pointer arithmetic with __ldg (read-only cache) for the
    // strided reduction loads, since the reduction stride (inner) is odd
    // and does not permit safe/aligned vectorized loads across r.
    auto mY = make_tensor(
        make_gmem_ptr(Y),
        make_shape(outer, inner),
        make_stride((int64_t)inner, (int64_t)1)
    );
    // Grid-stride loop: launch a grid sized to fill full waves on the GPU
    // (avoiding a small partial-wave tail) and let each thread process
    // multiple output elements if needed.
    for (int idx = blockIdx.x * blockDim.x + threadIdx.x; idx < total; idx += stride) {
        int o = idx / inner;
        int i = idx - o * inner;
        int64_t inner64 = (int64_t)inner;
        int64_t base = (int64_t)o * (int64_t)R * inner64 + (int64_t)i;
        int r = 0;
        float m0 = __ldg(X + base);
        float m1 = m0, m2 = m0, m3 = m0;
        r = 1;
        if (R >= 4) {
            m1 = __ldg(X + base + inner64);
            m2 = __ldg(X + base + 2 * inner64);
            m3 = __ldg(X + base + 3 * inner64);
            r = 4;
            #pragma unroll 4
            for (; r + 3 < R; r += 4) {
                m0 = fminf(m0, __ldg(X + base + (int64_t)r * inner64));
                m1 = fminf(m1, __ldg(X + base + (int64_t)(r + 1) * inner64));
                m2 = fminf(m2, __ldg(X + base + (int64_t)(r + 2) * inner64));
                m3 = fminf(m3, __ldg(X + base + (int64_t)(r + 3) * inner64));
            }
        }
        float m = fminf(fminf(m0, m1), fminf(m2, m3));
        for (; r < R; ++r) {
            m = fminf(m, __ldg(X + base + (int64_t)r * inner64));
        }
        mY(o, i) = m;
    }
}

torch::Tensor min_reduce_forward(torch::Tensor x, int64_t dim) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

    auto x_c = x.contiguous();
    int ndim = x_c.dim();
    if (dim < 0) dim += ndim;
    TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");

    int64_t outer = 1;
    for (int i = 0; i < dim; ++i) outer *= x_c.size(i);
    int64_t R = x_c.size(dim);
    int64_t inner = 1;
    for (int i = dim + 1; i < ndim; ++i) inner *= x_c.size(i);

    std::vector<int64_t> out_sizes;
    out_sizes.reserve(ndim - 1);
    for (int i = 0; i < ndim; ++i) {
        if (i != dim) out_sizes.push_back(x_c.size(i));
    }

    auto y = torch::empty(out_sizes, x_c.options());

    int64_t total = outer * inner;
    const int threads = 256;
    int neededBlocks = (int)((total + threads - 1) / threads);
    if (neededBlocks < 1) neededBlocks = 1;
    // Size the grid to a whole number of full waves on the device to avoid
    // a small partial-wave tail effect (as flagged by the profiler),
    // while covering all elements via a grid-stride loop inside the kernel.
    int device = 0;
    cudaGetDevice(&device);
    int numSM = 1;
    cudaDeviceGetAttribute(&numSM, cudaDevAttrMultiProcessorCount, device);
    int maxBlocksPerSM = 1;
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(&maxBlocksPerSM, min_reduce_kernel, threads, 0);
    int blocks = numSM * maxBlocksPerSM;
    if (blocks < 1) blocks = 1;
    if (blocks > neededBlocks) blocks = neededBlocks;
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    min_reduce_kernel<<<blocks, threads, 0, stream>>>(
        x_c.data_ptr<float>(),
        y.data_ptr<float>(),
        (int)outer, (int)R, (int)inner
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "min_reduce_kernel launch failed: ", cudaGetErrorString(err));

    return y;
}
"""

min_reduce_ext = load_inline(
    name="cute_min_reduce_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["min_reduce_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include",
                          "/root/cutegen_test/cutegen/cutlass/include/cute/"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Model that performs min reduction over a specific dimension using a
    custom CUTE-based CUDA kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self._ext = min_reduce_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.min_reduce_forward(x, self.dim)

